# ---------------------------------------------------------------------------------------------
# helpers
# ---------------------------------------------------------------------------------------------
def card(title, status, what, why, where, proof, src=None, extra=None):
    """status: live / shadow / closed / rule"""
    lab = {'live': 'LIVE', 'shadow': 'ΣΚΙΑ', 'closed': 'ΚΛΕΙΣΤΟ', 'rule': 'ΚΑΝΟΝΑΣ'}[status]
    h = f'<div class="mg-card {status}"><div class="mg-t">{title}<span class="tag {status}">{lab}</span></div>'
    if what:
        h += f'<div class="mg-row"><span class="mg-k">Τι κάνει:</span> {what}</div>'
    if why:
        h += f'<div class="mg-row"><span class="mg-k">Γιατί:</span> {why}</div>'
    if where:
        h += f'<div class="mg-row"><span class="mg-k">Πού ζει:</span> {where}</div>'
    if proof:
        h += f'<div class="mg-row"><span class="mg-k">Τεκμήριο:</span> {proof}</div>'
    if extra:
        h += extra
    if src:
        h += f'<div class="mg-src">{src}</div>'
    return h + '</div>'


def table(head, rows):
    h = '<table class="mg"><tr>' + ''.join(f'<th>{c}</th>' for c in head) + '</tr>'
    for r in rows:
        h += '<tr>' + ''.join(f'<td class="{"num" if i else ""}">{c}</td>' for i, c in enumerate(r)) + '</tr>'
    return h + '</table>'


def head(t, sub=''):
    return f'<div class="mg-h">{t}</div>' + (f'<div class="mg-sub">{sub}</div>' if sub else '')


def note(t):
    return f'<div class="mg-note">{t}</div>'


